// Combine all Google Ads data and prepare for Claude analysis
const clientData = $('Prepare Google Ads Queries').item.json;
const campaignData = $input.all()[0].json;
const keywordData = $input.all()[1].json;
const adData = $input.all()[2].json;
const searchTermsData = $input.all()[3].json;

// Helper function to convert micros to currency
const microsToCurrency = (micros) => {
  return micros ? (micros / 1000000).toFixed(2) : '0.00';
};

// Process campaign data
const campaigns = (campaignData.results || []).map(result => ({
  id: result.campaign?.id,
  name: result.campaign?.name,
  status: result.campaign?.status,
  impressions: result.metrics?.impressions || 0,
  clicks: result.metrics?.clicks || 0,
  conversions: result.metrics?.conversions || 0,
  cost: microsToCurrency(result.metrics?.costMicros),
  ctr: result.metrics?.ctr ? (result.metrics.ctr * 100).toFixed(2) + '%' : '0%',
  avg_cpc: microsToCurrency(result.metrics?.averageCpc),
  cost_per_conversion: microsToCurrency(result.metrics?.costPerConversion)
}));

// Process keyword data
const keywords = (keywordData.results || []).map(result => ({
  campaign_name: result.campaign?.name,
  ad_group_name: result.adGroup?.name,
  keyword: result.adGroupCriterion?.keyword?.text,
  match_type: result.adGroupCriterion?.keyword?.matchType,
  impressions: result.metrics?.impressions || 0,
  clicks: result.metrics?.clicks || 0,
  conversions: result.metrics?.conversions || 0,
  cost: microsToCurrency(result.metrics?.costMicros),
  ctr: result.metrics?.ctr ? (result.metrics.ctr * 100).toFixed(2) + '%' : '0%',
  cost_per_conversion: microsToCurrency(result.metrics?.costPerConversion)
}));

// Process ad data
const ads = (adData.results || []).map(result => ({
  campaign_name: result.campaign?.name,
  ad_group_name: result.adGroup?.name,
  ad_id: result.adGroupAd?.ad?.id,
  ad_type: result.adGroupAd?.ad?.type,
  impressions: result.metrics?.impressions || 0,
  clicks: result.metrics?.clicks || 0,
  conversions: result.metrics?.conversions || 0,
  cost: microsToCurrency(result.metrics?.costMicros),
  ctr: result.metrics?.ctr ? (result.metrics.ctr * 100).toFixed(2) + '%' : '0%',
  cost_per_conversion: microsToCurrency(result.metrics?.costPerConversion)
}));

// Process search terms for wasted spend analysis
const searchTerms = (searchTermsData.results || []).map(result => ({
  search_term: result.searchTermView?.searchTerm,
  match_type: result.segments?.searchTermMatchType,
  impressions: result.metrics?.impressions || 0,
  clicks: result.metrics?.clicks || 0,
  conversions: result.metrics?.conversions || 0,
  cost: microsToCurrency(result.metrics?.costMicros),
  ctr: result.metrics?.ctr ? (result.metrics.ctr * 100).toFixed(2) + '%' : '0%'
}));

// Calculate totals
const totals = campaigns.reduce((acc, camp) => {
  acc.total_impressions += camp.impressions;
  acc.total_clicks += camp.clicks;
  acc.total_conversions += camp.conversions;
  acc.total_cost += parseFloat(camp.cost);
  return acc;
}, {
  total_impressions: 0,
  total_clicks: 0,
  total_conversions: 0,
  total_cost: 0
});

totals.average_cpl = totals.total_conversions > 0 
  ? (totals.total_cost / totals.total_conversions).toFixed(2) 
  : 'N/A';

// Identify wasted spend (high cost, zero conversions)
const wastedSpend = keywords
  .filter(kw => parseFloat(kw.cost) > 10 && kw.conversions === 0)
  .sort((a, b) => parseFloat(b.cost) - parseFloat(a.cost))
  .slice(0, 20);

const performanceData = {
  account_info: {
    account_id: clientData.account_id,
    account_name: clientData.account_name,
    target_cpl: clientData.target_cpl,
    weekly_budget: clientData.weekly_budget,
    manager_id: clientData.manager_id,
    date_range: `${clientData.date_range.start} to ${clientData.date_range.end}`
  },
  summary: totals,
  campaigns: campaigns,
  keywords: keywords.slice(0, 50), // Top 50 by cost
  ads: ads.slice(0, 30), // Top 30 by cost
  search_terms: searchTerms.slice(0, 50), // Top 50 by cost
  wasted_spend_keywords: wastedSpend
};

return {
  json: {
    account_id: clientData.account_id,
    account_name: clientData.account_name,
    target_cpl: clientData.target_cpl,
    weekly_budget: clientData.weekly_budget,
    manager_id: clientData.manager_id,
    performance_data: performanceData
  }
};

