// Parse Claude's response and prepare email content
const accountName = $('Prepare Data for Claude').item.json.account_name;
const performanceData = $('Prepare Data for Claude').item.json.performance_data;
const claudeResponse = $input.item.json;

// Extract the JSON from Claude's response
let recommendations;
try {
  // Claude's response is in content[0].text
  const responseText = claudeResponse.content[0].text;
  // Try to parse JSON from the response
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    recommendations = JSON.parse(jsonMatch[0]);
  } else {
    // Fallback if no JSON found
    recommendations = {
      high_confidence_changes: [],
      review_required: [],
      insights: responseText
    };
  }
} catch (error) {
  recommendations = {
    high_confidence_changes: [],
    review_required: [],
    insights: 'Error parsing Claude response: ' + error.message
  };
}

// Format high confidence changes for email
const formatHighConfidence = (changes) => {
  if (!changes || changes.length === 0) return 'None identified';

  return changes.map((change, idx) => {
    return `${idx + 1}. [${change.type.toUpperCase()}] ${change.entity_name || 'N/A'}
   Reason: ${change.reason}
   Expected Impact: ${change.expected_impact}`;
  }).join('\n\n');
};

// Format review required items for email
const formatReviewRequired = (items) => {
  if (!items || items.length === 0) return 'None at this time';

  return items.map((item, idx) => {
    return `${idx + 1}. [${item.type.toUpperCase()}]
   Recommendation: ${item.recommendation}
   Reason: ${item.reason}
   Estimated Impact: ${item.estimated_impact}`;
  }).join('\n\n');
};

// Create email body
const emailSubject = `Google Ads Optimization Report - ${accountName}`;
const emailBody = `
Google Ads Lead Optimizer - Weekly Report
==========================================

Account: ${accountName}
Period: ${performanceData.account_info.date_range}

📊 PERFORMANCE SUMMARY
----------------------
Total Impressions: ${performanceData.summary.total_impressions.toLocaleString()}
Total Clicks: ${performanceData.summary.total_clicks.toLocaleString()}
Total Conversions: ${performanceData.summary.total_conversions}
Total Cost: $${performanceData.summary.total_cost.toFixed(2)}
Actual CPL: $${performanceData.summary.average_cpl}
Target CPL: $${performanceData.account_info.target_cpl}

🎯 KEY INSIGHTS
---------------
${recommendations.insights}

✅ HIGH CONFIDENCE CHANGES (Auto-Apply Ready)
--------------------------------------------
${formatHighConfidence(recommendations.high_confidence_changes)}

⚠️  CHANGES REQUIRING YOUR REVIEW
---------------------------------
${formatReviewRequired(recommendations.review_required)}

🔗 NEXT STEPS
-------------
1. Review the high confidence changes above
2. Click the approval link to confirm or reject changes
3. Review strategic recommendations that require your decision

[APPROVAL LINK PLACEHOLDER - Will be webhook in next version]

---
This report was generated automatically by the Google Ads Lead Optimizer.
Questions? Reply to this email.
`;

return {
  json: {
    account_name: accountName,
    account_id: $('Prepare Data for Claude').item.json.account_id,
    email_subject: emailSubject,
    email_body: emailBody,
    recommendations: recommendations,
    performance_summary: performanceData.summary
  }
};

// Prepare Google Ads API mutations to apply approved changes
// For now, we'll prepare the changes but won't apply them automatically
// This can be extended based on approval webhook response

const accountId = $('Format Email Report').item.json.account_id;
const recommendations = $('Format Email Report').item.json.recommendations;

// Only process high confidence changes
const changesToApply = recommendations.high_confidence_changes || [];

const mutations = [];

changesToApply.forEach(change => {
  switch(change.type) {
    case 'pause_keyword':
      mutations.push({
        operation: 'UPDATE',
        entity: 'ad_group_criterion',
        resourceName: change.entity_id,
        update: {
          status: 'PAUSED'
        },
        change_details: change
      });
      break;

    case 'adjust_bid':
      mutations.push({
        operation: 'UPDATE',
        entity: 'ad_group_criterion',
        resourceName: change.entity_id,
        update: {
          cpc_bid_micros: change.action_details.new_bid_micros
        },
        change_details: change
      });
      break;

    case 'add_negative':
      mutations.push({
        operation: 'CREATE',
        entity: 'campaign_criterion',
        create: {
          campaign: change.action_details.campaign_resource_name,
          keyword: {
            text: change.action_details.keyword_text,
            match_type: 'EXACT'
          },
          negative: true
        },
        change_details: change
      });
      break;

    case 'pause_ad':
      mutations.push({
        operation: 'UPDATE',
        entity: 'ad_group_ad',
        resourceName: change.entity_id,
        update: {
          status: 'PAUSED'
        },
        change_details: change
      });
      break;
  }
});

return {
  json: {
    account_id: accountId,
    account_name: $('Format Email Report').item.json.account_name,
    manager_id: $('Format Email Report').item.json.manager_id,
    mutations: mutations,
    total_changes: mutations.length
  }
};

// Prepare log entries for all changes applied
const accountName = $('Prepare Change Mutations').item.json.account_name;
const mutations = $('Prepare Change Mutations').item.json.mutations;
const apiResponse = $input.item.json;

const timestamp = new Date().toISOString();

// Create a log entry for each mutation
const logEntries = mutations.map((mutation, idx) => {
  const result = apiResponse.mutateOperationResponses?.[idx];

  return {
    Timestamp: timestamp,
    'Account Name': accountName,
    'Change Type': mutation.change_details.type,
    'Entity': mutation.change_details.entity_name || 'N/A',
    'Reason': mutation.change_details.reason,
    'Expected Impact': mutation.change_details.expected_impact,
    'Result': result?.mutateOperationResponse ? 'Success' : 'Failed',
    'Details': JSON.stringify(mutation.change_details.action_details || {})
  };
});

return logEntries.map(entry => ({ json: entry }));
